// CrowdStrike CQL for Zelle Recipient Enumeration via Multiple Failed Lookups
// Repository: flame-banking-a2a-processing
// Aggregation that cannot be expressed in Sigma:
// Original condition: selection | count() by account_id > 10
event_type="zelle_recipient_lookup"
lookup_result="not_found"
| groupBy(account_id, function=[count(as=event_count)])
| event_count > 10
